    cats=[('compressors','abk15-10tb','7 моделей · 7,5–75 кВт'),('receivers','rv-500-10','Объём 500 и 900 литров'),('separators','separator-lb13145-3','По артикулу и типоразмеру'),('oils','mol-compressol-r46-al','Масла, фильтры и комплектующие')]
    body+='<section class="section" id="directions"><div class="container">'+section_head('01','Оборудование','Соберите свою систему','От источника воздуха до расходного элемента. Компоненты подбираются под общую задачу.')+'<div class="category-grid">'
