    body+='</div></div></section>'
    body+='<section class="section system-section" id="systems"><div class="container">'+section_head('04','Система целиком','Воздух нужного качества.<br>В нужной точке.','Осушение и фильтрацию определяет технология. Схема показывает функции компонентов; порядок и состав уточняются проектом.')+'<ol class="system-flow">'+''.join(f'<li><small>0{i}</small><h3>{t}</h3><p>{d}</p></li>' for i,(t,d) in enumerate([('Компрессор','Создаёт поток сжатого воздуха.'),('Ресивер','Сглаживает колебания расхода.'),('Воздухоподготовка','Снижает влажность и загрязнения.'),('Производство','Получает воздух по требованиям процесса.')],1))+'</ol>'+link('#selection','Подобрать систему <span aria-hidden="true">↗</span>','btn primary')+'</div></section>'
    body+='<section class="section" id="about"><div class="container">'+section_head('05','Подход к работе','Решение начинается<br>с вашей задачи.','QazAirPress представлен в открытых источниках как поставщик компрессорного оборудования в Астане.',link('o-kompanii/index.html','О компании и источниках ↗','text-link'))+'<div class="benefits-grid">'+''.join(f'<article><span>0{i}</span><h3>{t}</h3><p>{d}</p></article>' for i,(t,d) in enumerate([('Параметры до покупки','Согласуем давление, расход и режим работы оборудования.'),('Система в комплекте','Проверяем потребность в ресивере, осушении и фильтрации.'),('Расходники по артикулу','Сверяем маркировку и посадочные размеры элементов.'),('Условия в предложении','Фиксируем состав, доставку и гарантийные условия в КП.')],1))+'</div></div></section>'
