def product(p):
    parts=[('Каталог','catalog/index.html'),(p['name'],'')];base='../';rows=''.join(f'<tr><th scope="row">{esc(k)}</th><td>{esc(v)}</td></tr>' for k,v in p['specs'])
    body='<section class="product-section"><div class="container">'+crumbs(base,parts)+f'<div class="product-detail-grid"><figure class="detail-photo">{photo(p,base,eager=True)}<figcaption>'+('Фото конкретного исполнения требуется подтвердить.' if p['photoStatus']=='needs-model-photo' else 'Фотография из соответствующей карточки QazAirPress на Satu.kz.')+f'</figcaption></figure><div class="detail-copy"><span class="eyebrow">{esc(CATS[p["categoryId"]])} / QazAirPress</span><h1>{esc(p["name"])}</h1><p>{esc(p["description"])}</p><div class="detail-highlights">'+''.join(f'<div><b>{esc(v)}</b><span>{esc(u)}</span></div>' for v,u in specs_short(p))+f'</div><div class="detail-price"><small>Цена по каталогу Satu.kz · 17.11.2026</small><strong>{esc(p["price"])}</strong><span>Актуальные цена, наличие и комплектация — в КП</span></div><div class="button-row">{cta(p["name"],"Получить КП на эту модель")}{link("../dostavka/index.html","Доставка по Казахстану ↗","text-link")}</div>'+('<p class="data-note">Промышленная совместимость не подтверждена. До проверки не рекомендуем позицию для компрессорной системы.</p>' if p['reviewOnly'] else '')+'</div></div></div></section>'
    body+=f'<section class="section tinted"><div class="container product-information"><div><span class="eyebrow">Техническая информация</span><h2>Характеристики</h2><div class="table-wrap"><table><caption>{esc(p["name"])} — параметры по источнику</caption><tbody>{rows}</tbody></table></div><p class="data-note">{esc(p["note"])}</p><a class="text-link" href="{esc(p["source"])}" rel="noopener" target="_blank">Карточка-источник на Satu.kz ↗</a></div><div class="product-notes"><article><h2>Применение</h2><p>{esc(p["application"])}</p></article><article><h2>Комплектация и совместимость</h2><p>{"Комплектация лазерного исполнения приведена по каталогу. Класс чистоты воздуха и совместимость со станком подтверждаются отдельно." if "laser" in p["slug"] else "Исполнение и состав поставки сверяются с паспортом и требованиями вашего оборудования. Комплектующие согласуются отдельно, если не указаны в таблице."}</p></article><article><h2>Поставка и гарантия</h2><p>Укажите город и условия разгрузки. Срок, стоимость доставки, гарантия и регламент обслуживания фиксируются в предложении до заказа.</p>{link("../dostavka/index.html","Как согласовать доставку ↗","text-link")}</article></div></div></section>'
    related=[x for x in P if x['slug']!=p['slug'] and x['categoryId']==p['categoryId'] and not x['reviewOnly']][:3]
    if related:body+='<section class="section"><div class="container">'+section_head('','Сравните варианты','Другие позиции категории')+'<div class="product-grid related-grid">'+''.join(card(x,base) for x in related)+'</div></div></section>'
    body+=f'<section class="section compact system-section"><div class="container inline-cta"><div><span class="eyebrow">Точный состав предложения</span><h2>Согласуем исполнение<br>под ваше оборудование.</h2></div>{cta(p["name"],"Обсудить эту модель")}</div></section>'
    schema={'@type':'Product','name':p['name'],'sku':p['slug'],'description':p['description'],'category':CATS[p['categoryId']],'url':SITE+'products/'+p['slug']+'.html','additionalProperty':[{'@type':'PropertyValue','name':k,'value':v} for k,v in p['specs']]}
    if p['photoStatus']!='needs-model-photo':schema['image']=SITE+'assets/products/'+p['slug']+'.webp'
    # No availability or unconfirmed brand. Oils use a per-litre price specification.
    if not p['reviewOnly']:
        offer={'@type':'Offer','url':schema['url'],'seller':{'@id':SITE+'#organization'},'priceCurrency':'KZT'}
        if p['unit']:offer['priceSpecification']={'@type':'UnitPriceSpecification','price':p['priceValue'],'priceCurrency':'KZT','referenceQuantity':{'@type':'QuantitativeValue','value':1,'unitCode':'LTR'}}
        else:offer['price']=p['priceValue']
        schema['offers']=offer
    return page('products/'+p['slug']+'.html',p['name']+' — характеристики, цена и поставка',p['description']+' Цена и комплектация по запросу КП, доставка по Казахстану.',body,parts,[schema],p['slug'] if p['photoStatus']!='needs-model-photo' else None)

